import type {
  ActivityAction,
  ActivityEvent,
} from "@/types/activity";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";

export function toApiToken(row: ApiTokenRow): ApiToken {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    userId: brandId<UserId>(row.userId),
    name: row.name,
    scope: row.scope as ApiTokenScope,
    prefix: row.prefix,
    expiresAt: brandStamp(row.expiresAt),
    lastUsedAt: brandStampOrNull(row.lastUsedAt),
    revokedAt: brandStampOrNull(row.revokedAt),
    createdAt: brandStamp(row.createdAt),
  };
}

export function toInvoice(row: InvoiceRow): Invoice {

/**
 * Personal API tokens. Reads that authenticate a raw token are keyed by hash;
 * every other read is filtered by `orgId`.
 */
import { and, count, desc, eq, gt, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

export type NewApiToken = {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly tokenHash: string;
  readonly prefix: string;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
};

export async function insertApiToken(input: NewApiToken): Promise<ApiToken> {
  const row = getDb()
    .insert(apiTokens)
    .values({
      id: newId(),
      orgId: input.orgId,
      userId: input.userId,
      name: input.name,
      scope: input.scope,
      tokenHash: input.tokenHash,
      prefix: input.prefix,
      expiresAt: input.expiresAt,
      lastUsedAt: null,
      revokedAt: null,
      createdAt: input.createdAt,
      updatedAt: input.createdAt,
    })
    .returning()
    .get();

  return toApiToken(row);
}

/** Newest first, including revoked and expired tokens. */
export async function listApiTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)),
    )
    .orderBy(desc(apiTokens.createdAt), desc(apiTokens.id))
    .all();

  return rows.map(toApiToken);
}

export async function findApiToken(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)),
    )
    .get();

  return row ? toApiToken(row) : null;
}

/**
 * The credential lookup. Like invitation acceptance, the hash is the key and
 * carries the tenant with it, so this read is not scoped by `orgId`.
 */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();

  return row ? toApiToken(row) : null;
}

/** Usable means not revoked and not yet expired (`expiresAt` is exclusive). */
export async function countUsableApiTokens(
  orgId: OrgId,
  userId: UserId,
  now: IsoTimestamp,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, now),
      ),
    )
    .get();

  return row?.value ?? 0;
}

/**
 * Sets `revokedAt` only when the token is not already revoked. Returns null
 * when the row is missing or was already revoked, so callers can avoid a
 * second audit entry.
 */
export async function revokeApiToken(
  orgId: OrgId,
  tokenId: string,
  revokedAt: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt, updatedAt: revokedAt })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();

  return row ? toApiToken(row) : null;
}

export async function touchApiTokenLastUsed(
  orgId: OrgId,
  tokenId: string,
  lastUsedAt: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt, updatedAt: toIsoTimestamp(new Date(lastUsedAt)) })
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)),
    )
    .run();
}

/**
 * Personal API tokens: mint, list, revoke and authenticate.
 *
 * The secret is returned once from `createApiToken` and stored only as a hash.
 * Creation and revocation are announced on the event bus; the audit log records
 * them from that side and never sees the secret.
 *
 * Must call (do not reimplement): assertOrgScope, emit, hashToken, hasRoleAtLeast
 */
import { emit } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { createApiTokenSchema } from "@/schemas/api-token";
import { toIsoTimestamp } from "@/types/common";
import { hasRoleAtLeast } from "@/types/member";
import { actorEnvelope, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Actor, Role } from "@/types/member";
import type { PermissionAction, PermissionDecision } from "@/types/permission";

/** A user may hold this many unrevoked, unexpired tokens in one organization. */
const MAX_USABLE_TOKENS = 5;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Public prefix of every secret, included in the stored `prefix`. */
const SECRET_PREFIX = "tfk_";

/** `prefix` is the first this many characters of the secret. */
const PREFIX_LENGTH = 12;

function permissionDenied(action: PermissionAction): never {
  const decision: PermissionDecision = {
    allowed: false,
    action,
    resourceKind: "organization",
    reason: "denied_by_role",
  };
  throw new PermissionDeniedError(action, decision);
}

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write" && !hasRoleAtLeast(actor.role, "member")) {
    permissionDenied("project:create");
  }

  const createdAtDate = new Date();
  const createdAt = toIsoTimestamp(createdAtDate);
  const usable = await apiTokenRepo.countUsableApiTokens(
    parsed.orgId,
    actor.userId,
    createdAt,
  );
  if (usable >= MAX_USABLE_TOKENS) {
    throw new Error(
      `A user may hold at most ${MAX_USABLE_TOKENS} usable API tokens in an organization`,
    );
  }

  const token = `${SECRET_PREFIX}${randomToken()}`;
  const expiresAt = toIsoTimestamp(
    new Date(createdAtDate.getTime() + parsed.expiresInDays * MS_PER_DAY),
  );

  const apiToken = await apiTokenRepo.insertApiToken({
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    tokenHash: hashToken(token),
    prefix: token.slice(0, PREFIX_LENGTH),
    expiresAt,
    createdAt,
  });

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);

  const targetUserId = userId ?? actor.userId;
  if (targetUserId !== actor.userId && !hasRoleAtLeast(actor.role, "admin")) {
    permissionDenied("member:remove");
  }

  return apiTokenRepo.listApiTokens(orgId, targetUserId);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiToken(orgId, tokenId),
    "ApiToken",
    tokenId,
  );

  if (existing.userId !== actor.userId && !hasRoleAtLeast(actor.role, "admin")) {
    permissionDenied("member:remove");
  }

  if (existing.revokedAt !== null) return existing;

  const revokedAt = toIsoTimestamp(new Date());
  const revoked = requireFound(
    await apiTokenRepo.revokeApiToken(orgId, tokenId, revokedAt),
    "ApiToken",
    tokenId,
  );

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    userId: revoked.userId,
    name: revoked.name,
  });

  return revoked;
}

/**
 * Revokes every still-active token the removed member holds in this
 * organization, including expired ones. Already-revoked rows keep their
 * original `revokedAt` and are not audited again. Tokens in other
 * organizations are left alone.
 */
export async function revokeApiTokensForRemovedMember(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const tokens = await apiTokenRepo.listApiTokens(orgId, userId);

  for (const token of tokens) {
    if (token.revokedAt !== null) continue;

    const revokedAt = toIsoTimestamp(new Date());
    const revoked = await apiTokenRepo.revokeApiToken(orgId, token.id, revokedAt);
    if (!revoked) continue;

    await emit("api_token.revoked", {
      ...actorEnvelope(actor),
      orgId,
      tokenId: revoked.id,
      userId: revoked.userId,
      name: revoked.name,
    });
  }
}

/**
 * Resolves the actor a raw token stands for. Unknown, revoked, expired,
 * orphaned (user no longer active, or the organization deleted) tokens
 * resolve to null and do not touch `lastUsedAt`. A `read` token is always a
 * viewer; a `write` token takes the member's role at the time of the call.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const apiToken = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (!apiToken) return null;

  const now = toIsoTimestamp(new Date());
  if (apiToken.revokedAt !== null) return null;
  if (apiToken.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (!org || isArchived(org)) return null;

  const member = await memberRepo.findMember(apiToken.orgId, apiToken.userId);
  if (!member || member.status !== "active") return null;

  await apiTokenRepo.touchApiTokenLastUsed(apiToken.orgId, apiToken.id, now);

  const role: Role = apiToken.scope === "read" ? "viewer" : member.role;
  return { userId: apiToken.userId, orgId: apiToken.orgId, role };
}

