  }

  const token = `${SECRET_PREFIX}${randomToken()}`;
  const expiresAt = toIsoTimestamp(
    new Date(createdAtDate.getTime() + parsed.expiresInDays * MS_PER_DAY),
  );

  const apiToken = await apiTokenRepo.insertApiToken({
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    tokenHash: hashToken(token),
    prefix: token.slice(0, PREFIX_LENGTH),
    expiresAt,
    createdAt,
  });

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
