import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { ZodError } from "zod";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { hashToken } from "@/lib/hash";
import { getDb, apiTokens } from "@/server/db";
import { eq } from "drizzle-orm";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as userRepo from "@/server/repositories/user-repository";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import * as apiTokenService from "@/server/services/api-token-service";
import * as memberService from "@/server/services/member-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";
import { toIsoTimestamp } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  tenant = await createTenant("tokens");
  other = await createTenant("tokens-other");
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

describe("api tokens", () => {
  it("covers the contract", async () => {
    await expect(
      apiTokenService.createApiToken(tenant.actors.member, {
        orgId: tenant.org.id,
        name: "   ",
        scope: "read",
        expiresInDays: 1,
      }),
    ).rejects.toBeInstanceOf(ZodError);

    await expect(
      apiTokenService.createApiToken(tenant.actors.member, {
        orgId: other.org.id,
        name: "nope",
        scope: "read",
        expiresInDays: 3,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      apiTokenService.createApiToken(tenant.actors.viewer, {
        orgId: tenant.org.id,
        name: "write",
        scope: "write",
        expiresInDays: 3,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const created = await apiTokenService.createApiToken(tenant.actors.viewer, {
      orgId: tenant.org.id,
      name: "  reader  ",
      scope: "read",
      expiresInDays: 2,
    });

    expect(created.token.startsWith("tfk_")).toBe(true);
    expect(created.apiToken.prefix).toBe(created.token.slice(0, 12));
    expect(created.apiToken.prefix).toHaveLength(12);
    expect(created.apiToken.name).toBe("reader");
    expect(created.apiToken.lastUsedAt).toBeNull();
    expect(created.apiToken.revokedAt).toBeNull();
    expect(created.apiToken.userId).toBe(tenant.userIds.viewer);
    expect(JSON.stringify(created.apiToken)).not.toContain(created.token);
    expect(JSON.stringify(created.apiToken)).not.toContain(hashToken(created.token));

    const expiresMs =
      new Date(created.apiToken.createdAt).getTime() + 2 * 24 * 60 * 60 * 1000;
    expect(created.apiToken.expiresAt).toBe(new Date(expiresMs).toISOString());

    const actor = await apiTokenService.authenticateApiToken(created.token);
    expect(actor).toEqual({
      userId: tenant.userIds.viewer,
      orgId: tenant.org.id,
      role: "viewer",
    });

    const listed = await apiTokenService.listApiTokens(
      tenant.actors.viewer,
      tenant.org.id,
    );
    expect(listed[0]?.id).toBe(created.apiToken.id);
    expect(listed[0]?.lastUsedAt).not.toBeNull();

    await expect(
      apiTokenService.listApiTokens(
        tenant.actors.member,
        tenant.org.id,
        tenant.userIds.viewer,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const adminList = await apiTokenService.listApiTokens(
      tenant.actors.admin,
      tenant.org.id,
      tenant.userIds.viewer,
    );
    expect(adminList).toHaveLength(1);

    const write = await apiTokenService.createApiToken(tenant.actors.member, {
      orgId: tenant.org.id,
      name: "writer",
      scope: "write",
      expiresInDays: 1,
    });
    const writeActor = await apiTokenService.authenticateApiToken(write.token);
    expect(writeActor?.role).toBe("member");

    await memberRepo.updateMemberRole(
      tenant.org.id,
      (await memberRepo.findMember(tenant.org.id, tenant.userIds.member))!.id,
      "admin",
    );
    const promoted = await apiTokenService.authenticateApiToken(write.token);
    expect(promoted?.role).toBe("admin");
    await memberRepo.updateMemberRole(
      tenant.org.id,
      (await memberRepo.findMember(tenant.org.id, tenant.userIds.member))!.id,
      "member",
    );

    const beforeFail = (await apiTokenService.listApiTokens(
      tenant.actors.viewer,
      tenant.org.id,
    ))[0]?.lastUsedAt;

    expect(await apiTokenService.authenticateApiToken("tfk_nope")).toBeNull();
    expect(await apiTokenService.authenticateApiToken(created.token + "x")).toBeNull();

    getDb()
      .update(apiTokens)
      .set({ expiresAt: created.apiToken.createdAt })
      .where(eq(apiTokens.id, created.apiToken.id))
      .run();
    expect(await apiTokenService.authenticateApiToken(created.token)).toBeNull();
    const afterFail = (await apiTokenService.listApiTokens(
      tenant.actors.viewer,
      tenant.org.id,
    ))[0]?.lastUsedAt;
    expect(afterFail).toBe(beforeFail);

    getDb()
      .update(apiTokens)
      .set({ expiresAt: created.apiToken.expiresAt })
      .where(eq(apiTokens.id, created.apiToken.id))
      .run();

    const ids: string[] = [created.apiToken.id];
    for (let i = 0; i < 4; i += 1) {
      const next = await apiTokenService.createApiToken(tenant.actors.viewer, {
        orgId: tenant.org.id,
        name: `t${i}`,
        scope: "read",
        expiresInDays: 10,
      });
      ids.push(next.apiToken.id);
    }
    await expect(
      apiTokenService.createApiToken(tenant.actors.viewer, {
        orgId: tenant.org.id,
        name: "sixth",
        scope: "read",
        expiresInDays: 10,
      }),
    ).rejects.toThrow();
    expect(
      await apiTokenService.listApiTokens(tenant.actors.viewer, tenant.org.id),
    ).toHaveLength(5);

    const revoked = await apiTokenService.revokeApiToken(
      tenant.actors.viewer,
      tenant.org.id,
      ids[1]!,
    );
    expect(revoked.revokedAt).not.toBeNull();
    const again = await apiTokenService.revokeApiToken(
      tenant.actors.viewer,
      tenant.org.id,
      ids[1]!,
    );
    expect(again.revokedAt).toBe(revoked.revokedAt);
    expect(await apiTokenService.authenticateApiToken(
      // token string not retained for ids[1]; auth of created still works
      created.token,
    )).not.toBeNull();

    const replacement = await apiTokenService.createApiToken(tenant.actors.viewer, {
      orgId: tenant.org.id,
      name: "after-revoke",
      scope: "read",
      expiresInDays: 4,
    });
    expect(replacement.apiToken.id).toBeTruthy();

    await expect(
      apiTokenService.revokeApiToken(
        tenant.actors.member,
        tenant.org.id,
        replacement.apiToken.id,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      apiTokenService.revokeApiToken(
        tenant.actors.viewer,
        tenant.org.id,
        "missing-token-id",
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    const audits = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["api_token.created", "api_token.revoked"],
      limit: 100,
      cursor: null,
    });
    const blob = JSON.stringify(audits.items);
    expect(blob).not.toContain(created.token);
    expect(blob).not.toContain(hashToken(created.token));
    expect(blob).not.toContain(replacement.token);
    expect(
      audits.items.some(
        (row) =>
          row.action === "api_token.revoked" &&
          row.subjectKind === "api_token" &&
          row.subjectId === ids[1] &&
          row.actorId === tenant.userIds.viewer,
      ),
    ).toBe(true);
    const revokeAudits = audits.items.filter((row) => row.subjectId === ids[1]);
    expect(revokeAudits.filter((row) => row.action === "api_token.revoked")).toHaveLength(1);

    // expired token still revoked on member removal, already-revoked not re-audited
    const doomed = await apiTokenService.createApiToken(tenant.actors.member, {
      orgId: tenant.org.id,
      name: "doomed",
      scope: "read",
      expiresInDays: 5,
    });
    getDb()
      .update(apiTokens)
      .set({ expiresAt: toIsoTimestamp(new Date(Date.now() - 1000)) })
      .where(eq(apiTokens.id, doomed.apiToken.id))
      .run();
    const already = await apiTokenService.createApiToken(tenant.actors.member, {
      orgId: tenant.org.id,
      name: "already",
      scope: "read",
      expiresInDays: 5,
    });
    const alreadyRevoked = await apiTokenService.revokeApiToken(
      tenant.actors.member,
      tenant.org.id,
      already.apiToken.id,
    );

    // same user in the other org keeps their token
    await memberRepo.insertMember(
      other.org.id,
      tenant.userIds.member,
      "member",
      null,
    );
    const foreign = await apiTokenService.createApiToken(
      { userId: tenant.userIds.member, orgId: other.org.id, role: "member" },
      {
        orgId: other.org.id,
        name: "foreign",
        scope: "read",
        expiresInDays: 5,
      },
    );

    const memberRow = await memberRepo.findMember(
      tenant.org.id,
      tenant.userIds.member,
    );
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: memberRow!.id,
    });

    const memberTokens = await apiTokenService.listApiTokens(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    const doomedRow = memberTokens.find((row) => row.id === doomed.apiToken.id);
    const alreadyRow = memberTokens.find((row) => row.id === already.apiToken.id);
    expect(doomedRow?.revokedAt).not.toBeNull();
    expect(alreadyRow?.revokedAt).toBe(alreadyRevoked.revokedAt);

    const foreignListed = await apiTokenService.listApiTokens(
      other.actors.owner,
      other.org.id,
      tenant.userIds.member,
    );
    expect(foreignListed.find((row) => row.id === foreign.apiToken.id)?.revokedAt).toBeNull();
    expect(await apiTokenService.authenticateApiToken(foreign.token)).not.toBeNull();
    expect(await apiTokenService.authenticateApiToken(doomed.token)).toBeNull();
    expect(await apiTokenService.authenticateApiToken(write.token)).toBeNull();

    const removalAudits = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["api_token.revoked"],
      subjectKind: "api_token",
      limit: 100,
      cursor: null,
    });
    const doomedAudits = removalAudits.items.filter(
      (row) => row.subjectId === doomed.apiToken.id,
    );
    expect(doomedAudits).toHaveLength(1);
    expect(doomedAudits[0]?.actorId).toBe(tenant.userIds.owner);
    const alreadyAudits = removalAudits.items.filter(
      (row) => row.subjectId === already.apiToken.id,
    );
    expect(alreadyAudits).toHaveLength(1);
    expect(alreadyAudits[0]?.actorId).toBe(tenant.userIds.member);

    await orgRepo.archiveOrg(other.org.id);
    expect(await apiTokenService.authenticateApiToken(foreign.token)).toBeNull();

    // read token of an owner stays viewer
    const ownerTok = await apiTokenService.createApiToken(other.actors.owner, {
      orgId: other.org.id,
      name: "nope-deleted-org",
      scope: "write",
      expiresInDays: 1,
    });
    // org is archived, create still works (we don't check org liveness on create)
    expect(ownerTok.apiToken.scope).toBe("write");

    void userRepo;
  });
});

